from darts import TimeSeries
import pandas as pd, numpy as np
s=TimeSeries.from_times_and_values(pd.date_range('2020-01-01', periods=3, freq='h'), np.arange(3.0))
print([m for m in dir(s) if 'value' in m or 'quantile' in m or 'series' in m or 'data' in m][:80])
print('values shape', s.values().shape)
try: print('all_values', s.all_values().shape)
except Exception as e: print('all fail', e)
try: print('pd_series', s.pd_series())
except Exception as e: print('pd_series fail', e)
try: print('to_series', s.to_series())
except Exception as e: print('to_series fail', e)
